<?php $id=(int)($_GET['id']??0);$page_title=$id?'Edit Request':'Create Request';require_once __DIR__.'/includes/header.php';$r=$id?one('SELECT * FROM trial_requests WHERE id=?',[$id]):['name'=>'','email'=>'','whatsapp'=>'','country'=>'','dial_code'=>'','device'=>'','plan'=>'Free Trial','message'=>'','ip_address'=>'','status'=>'pending'];if(is_post()){verify_csrf();$data=[trim($_POST['name']),trim($_POST['email']),trim($_POST['whatsapp']),trim($_POST['country']),trim($_POST['dial_code']),trim($_POST['device']),trim($_POST['plan']),trim($_POST['message']),trim($_POST['ip_address']),$_POST['status']];if($id){$data[]=$id;query('UPDATE trial_requests SET name=?,email=?,whatsapp=?,country=?,dial_code=?,device=?,plan=?,message=?,ip_address=?,status=? WHERE id=?',$data);}else{query('INSERT INTO trial_requests (name,email,whatsapp,country,dial_code,device,plan,message,ip_address,status) VALUES (?,?,?,?,?,?,?,?,?,?)',$data);$id=db()->lastInsertId();create_notification('trial_request.created','admin','New trial request',$_POST['name']);}flash('success','Request saved.');redirect('request-view.php?id='.$id);} ?><div class="card"><div class="card-body"><form method="post"><?=csrf_field()?><div class="row"><?php foreach(['name'=>'Name','email'=>'Email','whatsapp'=>'WhatsApp','country'=>'Country','dial_code'=>'Dial Code','device'=>'Device','plan'=>'Plan','ip_address'=>'IP Address'] as $f=>$l): ?><div class="col-md-6"><label class="form-label"><?=$l?></label><input class="form-control mb-3" name="<?=$f?>" value="<?=e($r[$f])?>" <?=$f==='name'||$f==='whatsapp'||$f==='plan'?'required':''?>></div><?php endforeach; ?><div class="col-md-6"><label class="form-label">Status</label><select class="form-select mb-3" name="status"><?php foreach(['pending','approved','rejected','processed'] as $s): ?><option value="<?=$s?>" <?=$r['status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Message</label><textarea class="form-control mb-3" name="message" rows="5"><?=e($r['message'])?></textarea></div></div><button class="btn btn-primary">Save</button></form></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
